select count(*) filter (where notified_at is null) as pendientes_sin_notificar,
       count(*) filter (where status = 'open') as abiertas_total
from public.escalations;

parameters.jsCode:
const metrics = $('Calcular métricas del día anterior').first().json;
const esc = $('Escalaciones pendientes').first().json;
const appts = $('Citas de hoy').all().map(i => i.json);

let text = `Buenos días, Nairobi. Resumen de ayer y hoy:\n\n`;
text += `Ayer: ${metrics.new_leads} leads nuevos, ${metrics.quotes_created} cotizaciones, ${metrics.policies_sold} pólizas vendidas (${metrics.gross_premium} en prima bruta).\n`;
text += `Comisiones acumuladas ayer: ${metrics.commissions_accrued}. Mora total actual: ${metrics.overdue_amount}.\n`;
if (esc.abiertas_total > 0) text += `Tienes ${esc.abiertas_total} escalación(es) abierta(s)`;
if (esc.pendientes_sin_notificar > 0) text += `, ${esc.pendientes_sin_notificar} de anoche que no te desperté.`;
if (esc.abiertas_total > 0) text += ` Revísalas en la app.\n`;
if (appts.length > 0) {
  text += `Citas de hoy:\n` + appts.map(a => `- ${a.starts_at}: ${a.full_name} (${a.title})`).join('\n');
} else {
  text += `Sin citas agendadas para hoy.`;
}
return [{ json: { digest_text: text } }];

parameters.query:
select count(*)::int as solapes from public.appointments
where status in ('scheduled','confirmed')
  and tstzrange(starts_at, ends_at) && tstzrange($1::timestamptz, $2::timestamptz);

select to_char(slot_start, 'YYYY-MM-DD"T"HH24:MI:SSOF') as slot_start
from (
  select generate_series(
    date_trunc('hour', now()) + interval '1 hour',
    date_trunc('hour', now()) + interval '3 days',
    interval '1 hour'
  ) as slot_start
) s
where extract(hour from slot_start) between 8 and 18
and not exists (
  select 1 from public.appointments a
  where a.status in ('scheduled','confirmed')
  and tstzrange(a.starts_at, a.ends_at) && tstzrange(slot_start, slot_start + interval '1 hour')
)
limit 3;

insert into public.appointments (contact_id, title, purpose, starts_at, ends_at, status)
select c.id, $2, $3, $4::timestamptz, $5::timestamptz, 'scheduled'
from public.contacts c where c.phone = regexp_replace($1, '\D', '', 'g')
returning id, starts_at, ends_at;
